#!/bin/sh
# Generated by seaworthy: acme-agent, pacman, before removal. See seaworthy::scripts.
set -e
systemd_running() { [ -d /run/systemd/system ]; }
has_systemctl() { command -v systemctl >/dev/null 2>&1; }
try() { "$@" || echo "acme-agent: warning: '$*' failed (exit $?); continuing" >&2; }
action=remove
if [ "$action" = remove ] && has_systemctl; then
  if systemd_running; then try systemctl stop AcmeAgent-update.path AcmeAgent-update.service AcmeAgent.service; fi
  try systemctl disable AcmeAgent-update.path AcmeAgent.service
fi
